function formatDuration(seconds: number) {
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  return hours ? `${hours}時間${minutes}分` : `${minutes}分`;
}

type CsvEntryDraft = { front: string; back: string; writingAnswer: string | null };
type CsvPreview = { entries: CsvEntryDraft[]; headers: string[] };

function parseCsvRow(row: string) {
  const cells: string[] = [];
  let value = "";
  let quoted = false;
  for (let index = 0; index < row.length; index += 1) {
    const char = row[index];
    if (char === '"' && row[index + 1] === '"' && quoted) { value += '"'; index += 1; }
    else if (char === '"') quoted = !quoted;
    else if (char === "," && !quoted) { cells.push(value.trim()); value = ""; }
    else value += char;
  }
  cells.push(value.trim());
  return cells;
}

function findCsvColumn(headers: string[], names: string[]) {
  return headers.findIndex(header => names.includes(header.trim().toLowerCase()));
}

function parseCsv(raw: string, category: Category): CsvPreview {
  const rows = raw.replace(/^\uFEFF/, "").split(/\r?\n/).map(row => row.trim()).filter(Boolean).map(parseCsvRow);
  if (!rows.length) throw new Error("単語データを含むCSVを選択してください");
  const first = rows[0] ?? [];
  const leftNames = category === "english" ? ["英単語", "english", "word", "単語"] : ["漢字", "kanji"];
  const rightNames = category === "english" ? ["意味", "meaning", "日本語"] : ["読み", "よみ", "reading"];
  const hasHeader = findCsvColumn(first, leftNames) >= 0 && findCsvColumn(first, rightNames) >= 0;
  const headers = hasHeader ? first : [category === "english" ? "英単語" : "漢字", category === "english" ? "意味" : "読み", ...(category === "kanji" ? ["書き取り答え"] : [])];
  const dataRows = hasHeader ? rows.slice(1) : rows;
  const leftIndex = hasHeader ? findCsvColumn(first, leftNames) : 0;
  const rightIndex = hasHeader ? findCsvColumn(first, rightNames) : 1;
  const writingIndex = hasHeader ? findCsvColumn(first, ["書き取り", "書き取り答え", "writing"]) : 2;
  const entries = dataRows.map(cells => {
    const left = cells[leftIndex]?.trim();
    const right = cells[rightIndex]?.trim();
    if (!left || !right) return null;
    return category === "english" ? { front: right, back: left, writingAnswer: null } : { front: left, back: right, writingAnswer: cells[writingIndex]?.trim() || left };
  }).filter((entry): entry is CsvEntryDraft => Boolean(entry));
  if (!entries.length) throw new Error("2列以上の単語データが見つかりませんでした");
  return { entries, headers };
}

function downloadTextFile(filename: string, content: string) {
  const url = URL.createObjectURL(new Blob([content], { type: "text/csv;charset=utf-8" }));
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  URL.revokeObjectURL(url);
}

function daysInCurrentMonth() {
  const now = new Date();
  const start = startOfMonth(now);
  const days = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
  return Array.from({ length: start.getDay() + days }, (_, index) => index < start.getDay() ? null : new Date(now.getFullYear(), now.getMonth(), index - start.getDay() + 1));
}

